public class InnerKnowledgeBaseMediaExtractionConfigurationFactory(Action<Humidifier.QuickSight.KnowledgeBaseTypes.MediaExtractionConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.QuickSight.KnowledgeBaseTypes.MediaExtractionConfiguration>
{

    internal InnerKnowledgeBaseVideoExtractionConfigurationFactory VideoExtractionConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseAudioExtractionConfigurationFactory AudioExtractionConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseImageExtractionConfigurationFactory ImageExtractionConfigurationFactory { get; set; }

    protected override Humidifier.QuickSight.KnowledgeBaseTypes.MediaExtractionConfiguration Create()
    {
        var mediaExtractionConfigurationResult = CreateMediaExtractionConfiguration();
        factoryAction?.Invoke(mediaExtractionConfigurationResult);

        return mediaExtractionConfigurationResult;
    }

    private Humidifier.QuickSight.KnowledgeBaseTypes.MediaExtractionConfiguration CreateMediaExtractionConfiguration()
    {
        var mediaExtractionConfigurationResult = new Humidifier.QuickSight.KnowledgeBaseTypes.MediaExtractionConfiguration();

        return mediaExtractionConfigurationResult;
    }
    public override void CreateChildren(Humidifier.QuickSight.KnowledgeBaseTypes.MediaExtractionConfiguration result)
    {
        base.CreateChildren(result);

        result.VideoExtractionConfiguration ??= VideoExtractionConfigurationFactory?.Build();
        result.AudioExtractionConfiguration ??= AudioExtractionConfigurationFactory?.Build();
        result.ImageExtractionConfiguration ??= ImageExtractionConfigurationFactory?.Build();
    }

} // End Of Class

